use std::sync::Arc;

use crate::core::error::MemoryError;
use crate::core::traits::MemoryLayer;
use crate::core::types::{
    generate_memory_id, Fact, LayerId, Memory, MemoryContent, MemoryInput, Query,
};
use crate::core::MemoryResult;

use super::embedding::{build_embedding_model, EmbeddingConfig, EmbeddingModel};
use super::hnsw::{HnswConfig, HnswIndex};
use super::storage::L2Storage;
use super::time_graph::TimeGraph;
use super::write_buffer::{WriteBuffer, WriteBufferConfig};

#[derive(Debug, Clone)]
pub struct L2Config {
    pub hnsw: HnswConfig,
    pub write_buffer: WriteBufferConfig,
    pub dimension: usize,
    pub embedding: EmbeddingConfig,
}

impl Default for L2Config {
    fn default() -> Self {
        Self {
            hnsw: HnswConfig::default(),
            write_buffer: WriteBufferConfig::default(),
            dimension: 384,
            embedding: EmbeddingConfig::default(),
        }
    }
}

/// L2 approximate semantic memory layer.
///
/// Dual-index architecture:
/// - HNSW for semantic (vector) similarity search
/// - TimeGraph for temporal/relational queries
/// - WriteBuffer for batched ingestion
/// - L2Storage for persistent memory records
///
/// Embeddings are generated by a configurable `EmbeddingModel`.
/// Default is hash-based; enable MLX for real neural embeddings.
pub struct L2Engine {
    config: L2Config,
    pub hnsw: HnswIndex,
    /// 时间感知图。以 `Arc` 共享, 使 Phase2 RamblingEngine 能基于同一张
    /// 关系图做联想(它持有独立的 `Arc<TimeGraph>` 副本则看不到记忆关系)。
    pub graph: Arc<TimeGraph>,
    pub storage: L2Storage,
    write_buffer: Arc<WriteBuffer>,
    embedder: Box<dyn EmbeddingModel>,
    embedding_kind: &'static str,
}

impl L2Engine {
    pub fn new(config: L2Config) -> Self {
        let dim = config.dimension;
        let hnsw_config = HnswConfig {
            dimension: dim,
            distance: if super::embedding::uses_mlx_embeddings(&config.embedding)
                && config.hnsw.distance == HnswConfig::default().distance
            {
                // Cosine is the natural metric for normalized neural embeddings;
                // explicit Euclidean selection (A/B) is still honored above.
                super::hnsw::DistanceMetric::Cosine
            } else {
                config.hnsw.distance
            },
            ..config.hnsw.clone()
        };
        let wb = Arc::new(WriteBuffer::new(config.write_buffer.clone()));
        Arc::clone(&wb).start_background_flush();
        // Ensure embedder dimension matches the canonical dimension
        let mut embedding_config = config.embedding.clone();
        embedding_config.dimension = dim;
        let embedder = build_embedding_model(&embedding_config);
        Self {
            config: config.clone(),
            hnsw: HnswIndex::new(hnsw_config),
            graph: Arc::new(TimeGraph::new()),
            storage: L2Storage::new(),
            write_buffer: wb,
            embedder,
            embedding_kind: if super::embedding::uses_mlx_embeddings(&embedding_config) {
                "mlx"
            } else {
                "hash-fallback"
            },
        }
    }

    /// Which embedder is active — surfaced through memory status so the UI
    /// can show when semantic recall is running on the hash fallback.
    pub fn embedding_kind(&self) -> &'static str {
        self.embedding_kind
    }

    pub fn config(&self) -> &L2Config {
        &self.config
    }

    /// Insert a memory into L2 indices.
    ///
    /// Flow: extract text → feature vector → HNSW → TimeGraph (if Fact) → L2Storage → WriteBuffer
    pub fn insert(&self, input: MemoryInput) -> MemoryResult<u64> {
        self.insert_with_id(input, generate_memory_id())
    }

    /// Insert with a pre-determined ID.
    /// Used by MemoryRouter to keep IDs consistent across layers.
    pub fn insert_with_id(&self, input: MemoryInput, id: u64) -> MemoryResult<u64> {
        let memory = Memory::from_input_with_id(input, id);

        let content_text = memory.content_text();
        let vector = self.embedder.embed(&content_text);

        if content_text.len() > 2 {
            self.hnsw.insert(id, vector);
        }

        let content = memory.content.clone();
        if let MemoryContent::Fact(ref fact) = content {
            self.add_to_graph(id, fact);
        }

        self.storage.store(memory)?;

        let _ = self.write_buffer.add(MemoryInput {
            content,
            importance: 0.0,
            alias: None,
            tags: Vec::new(),
            layer: LayerId::L2,
        });

        Ok(id)
    }

    /// Batch insert multiple memories atomically.
    ///
    /// Each input is inserted following the same flow as `insert()`.
    /// Returns a vector of results, one per input, in the same order.
    /// Individual failures do not abort the batch — the vector may contain
    /// both Ok and Err entries.
    pub fn insert_batch(&self, inputs: Vec<MemoryInput>) -> Vec<MemoryResult<u64>> {
        inputs.into_iter().map(|input| self.insert(input)).collect()
    }

    /// Semantic (HNSW) search: find k nearest neighbors by vector similarity.
    pub fn search_semantic(&self, query: &Query, k: usize) -> Vec<(u64, f32)> {
        let vec = match query.embedding() {
            Some(emb) if emb.len() == self.config.dimension => emb.to_vec(),
            _ => self.embedder.embed(query.text().unwrap_or("")),
        };

        if self.hnsw.is_empty() {
            return Vec::new();
        }

        self.hnsw.search(&vec, k)
    }

    /// Temporal/relational search via TimeGraph.
    pub fn search_temporal(
        &self,
        entity_id: u64,
        relation: Option<&str>,
        time_after: Option<i64>,
        time_before: Option<i64>,
    ) -> Vec<(u64, String, f32)> {
        self.graph
            .query_neighbors(entity_id, relation, time_after, time_before)
            .into_iter()
            .map(|(edge, _)| (edge.target, edge.relation, edge.weight))
            .collect()
    }

    pub fn get_by_id(&self, id: u64) -> Option<Memory> {
        self.storage.get(id)
    }

    /// In-place metadata update (e.g. `superseded_by`) without re-embedding
    /// or touching the HNSW index.
    pub fn update_metadata<F>(&self, id: u64, f: F) -> bool
    where
        F: FnOnce(&mut crate::core::MemoryMeta),
    {
        self.storage.update_metadata(id, f)
    }

    pub fn remove(&self, id: u64) -> bool {
        let removed = self.storage.remove(id);
        self.hnsw.remove(id);
        self.graph.remove_node(id);
        removed
    }

    pub fn stats(&self) -> L2Stats {
        L2Stats {
            vectors: self.hnsw.len(),
            graph_nodes: self.graph.node_count(),
            graph_edges: self.graph.edge_count(),
            stored: self.storage.len(),
            buffer: self.write_buffer.len(),
        }
    }

    pub fn flush(&self) -> Vec<MemoryInput> {
        self.write_buffer.flush()
    }

    /// Generate an embedding vector using the configured model.
    /// pub(crate) for consolidation & external callers.
    pub(crate) fn text_to_vector(&self, text: &str) -> Vec<f32> {
        self.embedder.embed(text)
    }

    fn add_to_graph(&self, id: u64, fact: &Fact) {
        let subject_hash = Self::str_to_id(&fact.subject);
        let object_hash = Self::str_to_id(&fact.object);

        self.graph.add_node(id, vec![fact.subject.clone()]);
        self.graph.add_node(subject_hash, vec![]);
        self.graph.add_node(object_hash, vec![]);

        self.graph
            .add_edge(id, subject_hash, "has_subject".into(), 1.0);
        self.graph
            .add_edge(id, object_hash, "has_object".into(), 1.0);
        self.graph.add_edge(
            subject_hash,
            object_hash,
            fact.predicate.clone(),
            fact.confidence,
        );
    }

    fn str_to_id(s: &str) -> u64 {
        s.bytes()
            .fold(0u64, |acc, b| acc.wrapping_mul(31).wrapping_add(b as u64))
    }
}

impl MemoryLayer for L2Engine {
    fn read(&self, query: &Query) -> Result<Option<Memory>, MemoryError> {
        if let Some(id) = query.hash_key() {
            return Ok(self.storage.get(id));
        }

        let semantic_results = self.search_semantic(query, 1);
        if let Some(&(id, _)) = semantic_results.first() {
            return Ok(self.storage.get(id));
        }

        Ok(None)
    }

    fn write(&self, memory: MemoryInput) -> Result<(), MemoryError> {
        self.insert(memory)?;
        Ok(())
    }

    fn could_contain(&self, query: &Query) -> bool {
        if query.hash_key().is_some() {
            return true;
        }
        if query.embedding().is_some() {
            return !self.hnsw.is_empty();
        }
        if query.text().is_some() {
            return !self.storage.is_empty();
        }
        false
    }

    fn len(&self) -> usize {
        self.storage.len()
    }

    fn is_empty(&self) -> bool {
        self.storage.is_empty()
    }
}

#[derive(Debug, Clone)]
pub struct L2Stats {
    pub vectors: usize,
    pub graph_nodes: usize,
    pub graph_edges: usize,
    pub stored: usize,
    pub buffer: usize,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::Fact;

    fn make_l2() -> L2Engine {
        L2Engine::new(L2Config {
            hnsw: HnswConfig {
                m: 8,
                m_max: 16,
                ef_construction: 50,
                ef_search: 50,
                dimension: 16,
                ..Default::default()
            },
            dimension: 16,
            ..Default::default()
        })
    }

    fn make_input(text: &str) -> MemoryInput {
        MemoryInput::new(MemoryContent::Fact(Fact::new("user", "says", text)))
    }

    #[test]
    fn test_new_engine_empty() {
        let l2 = make_l2();
        assert!(l2.is_empty());
        assert_eq!(l2.len(), 0);
    }

    #[test]
    fn test_insert_and_get() {
        let l2 = make_l2();
        let id = l2.insert(make_input("hello world")).unwrap();
        let mem = l2.get_by_id(id);
        assert!(mem.is_some());
        assert_eq!(mem.unwrap().id, id);
    }

    #[test]
    fn test_insert_batch() {
        let l2 = make_l2();
        let inputs = vec![
            make_input("first entry"),
            make_input("second entry"),
            make_input("third entry"),
        ];
        let results = l2.insert_batch(inputs);
        assert_eq!(results.len(), 3);
        for r in &results {
            assert!(r.is_ok(), "all batch inserts should succeed");
        }
        // Verify all are retrievable
        for r in &results {
            let id = r.as_ref().unwrap();
            assert!(l2.get_by_id(*id).is_some(), "id {} should exist", id);
        }
        assert_eq!(l2.storage.len(), 3);
    }

    #[test]
    fn test_search_semantic() {
        let l2 = make_l2();
        l2.insert(make_input("rust programming")).unwrap();
        l2.insert(make_input("python programming")).unwrap();
        l2.insert(make_input("cooking pasta")).unwrap();

        let query = Query::by_text("rust code");
        let results = l2.search_semantic(&query, 3);
        assert!(!results.is_empty());
    }

    #[test]
    fn test_search_temporal() {
        let l2 = make_l2();
        let fact = Fact::new("alice", "knows", "bob");
        let input = MemoryInput::new(MemoryContent::Fact(fact));
        let _id = l2.insert(input).unwrap();

        let alice_id = L2Engine::str_to_id("alice");
        let bob_id = L2Engine::str_to_id("bob");

        let results = l2.search_temporal(alice_id, Some("knows"), None, None);
        assert!(!results.is_empty());
        let has_bob = results.iter().any(|(target, _, _)| *target == bob_id);
        assert!(has_bob);
    }

    #[test]
    fn test_remove() {
        let l2 = make_l2();
        let id = l2.insert(make_input("to delete")).unwrap();
        assert!(!l2.is_empty());
        assert!(l2.remove(id));
        assert!(l2.is_empty());
    }

    #[test]
    fn test_memory_layer_trait() {
        let l2 = make_l2();
        let input = make_input("layer test");
        let id = l2.insert(input.clone()).unwrap();

        let query = Query::by_id(id);
        let result = l2.read(&query).unwrap();
        assert!(result.is_some());
        assert_eq!(result.unwrap().id, id);

        assert!(l2.could_contain(&query));
    }

    #[test]
    fn test_stats() {
        let l2 = make_l2();
        l2.insert(make_input("stats test")).unwrap();
        let stats = l2.stats();
        assert_eq!(stats.stored, 1);
        assert_eq!(stats.vectors, 1);
    }

    #[test]
    fn test_text_to_vector() {
        let l2 = make_l2();
        let v1 = l2.text_to_vector("hello world");
        let v2 = l2.text_to_vector("hello world");
        let v3 = l2.text_to_vector("different text");

        assert_eq!(v1.len(), 16);
        assert_eq!(v1, v2);
        assert_ne!(v1, v3);
    }

    #[test]
    fn test_flush() {
        let l2 = make_l2();
        l2.insert(make_input("flush me")).unwrap();
        let batch = l2.flush();
        assert!(!batch.is_empty());
    }
}
